
import '../screens/common/shared_screen_stubs.dart';

/// A registry for screens generated by the PrimeCare UI Factory.
class ScreenRegistry {
  static const Map<String, dynamic> screens = {
    // PSW Role
    'SCREEN_PSW_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Dashboard'),
    'SCREEN_PSW_SHIFT_TRACKER': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Shift Tracker'),
    'SCREEN_PSW_CLIENTS': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Clients'),
    'SCREEN_PSW_TASKS': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Tasks'),
    'SCREEN_PSW_MESSAGES': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Messages'),
    'SCREEN_PSW_VISIT_NOTES': ScreenNotImplementedView(screenName: 'Not Implemented: PSW Visit Notes'),

    // RN Role
    'SCREEN_RN_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: RN Dashboard'),
    'SCREEN_RN_ASSESSMENTS': ScreenNotImplementedView(screenName: 'Not Implemented: RN Assessments'),
    'SCREEN_RN_CARE_PLANS': ScreenNotImplementedView(screenName: 'Not Implemented: RN Care Plans'),

    // RPN Role
    'SCREEN_RPN_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: RPN Dashboard'),

    // Coordinator Role
    'SCREEN_COORDINATOR_HUB': ScreenNotImplementedView(screenName: 'Not Implemented: Coordinator Hub'),
    'SCREEN_COORDINATOR_DISPATCH_MAP': ScreenNotImplementedView(screenName: 'Not Implemented: Coordinator Dispatch Map'),
    'SCREEN_COORDINATOR_SOS': ScreenNotImplementedView(screenName: 'Not Implemented: Coordinator SOS'),
    'SCREEN_COORDINATOR_WAITLIST': ScreenNotImplementedView(screenName: 'Not Implemented: Coordinator Waitlist'),

    // Allied Health
    'SCREEN_PT_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: PT Dashboard'),
    'SCREEN_RMT_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: RMT Dashboard'),
    'SCREEN_SW_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: SW Dashboard'),
    'SCREEN_CHIRO_DASHBOARD': ScreenNotImplementedView(screenName: 'Not Implemented: Chiro Dashboard'),
  };

  static List<dynamic> getAllScreens() => screens.values.toList();

  static List<ScreenAuditReport> auditRegistry() {
    return screens.keys
        .map(
          (id) => ScreenAuditReport(
            id: id,
            isHealthy: true,
            message: 'Screen $id is operational.',
          ),
        )
        .toList();
  }

  static Future<void> bootstrap() async {
    // Initialize the screen registry and synchronize with implementation code.
    print(
      'SCREEN_REGISTRY: Bootstrapping system registries with ${screens.length} screens...',
    );
  }
}

class ScreenAuditReport {
  final String id;
  final bool isHealthy;
  final String message;

  ScreenAuditReport({
    required this.id,
    required this.isHealthy,
    required this.message,
  });
}
